public class ResultsWorker(Channel<ScanResult> ch, IServiceScopeFactory sf,
    ILogger<ResultsWorker> log) : BackgroundService {
  protected override async Task ExecuteAsync(CancellationToken ct) {
    await foreach (var r in ch.Reader.ReadAllAsync(ct)) {
      try {
        using var scope = sf.CreateScope();
        var svc = scope.ServiceProvider.GetRequiredService<IResultProcessor>();
        await svc.ProcessAsync(r, ct);
      } catch (Exception ex) { log.LogError(ex, "Result {Id} failed", r.Id); }
    }
  }
}

