public class AuditInterceptor(ICurrentUser user) : SaveChangesInterceptor {
  public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
      DbContextEventData e, InterceptionResult<int> r, CancellationToken ct = default) {
    foreach (var en in e.Context!.ChangeTracker.Entries<IAuditable>()
             .Where(x => x.State is EntityState.Modified or EntityState.Added))
      foreach (var p in en.Properties.Where(p => p.IsModified || en.State == EntityState.Added))
        e.Context.Add(new AuditEntry(en.Metadata.Name, p.Metadata.Name,
          p.OriginalValue?.ToString(), p.CurrentValue?.ToString(), user.Id, DateTime.UtcNow));
    return base.SavingChangesAsync(e, r, ct);
  }
}

