buildForm(fields: FieldDef[]): FormGroup {
  const group: Record<string, FormControl> = {};
  for (const f of fields) {
    const v: ValidatorFn[] = [];
    if (f.required) v.push(Validators.required);
    if (f.max != null) v.push(Validators.max(f.max));
    if (f.pattern) v.push(Validators.pattern(f.pattern));
    group[f.key] = new FormControl(f.default ?? null, v);
  }
  return new FormGroup(group);
}

